public:
    int longestValidParentheses(string s) {
        vector<int> st = {-1};
        int maxLen = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            if (s[i] == '(') {
                st.push_back(i);
            } else {
                st.pop_back();
                if (st.empty()) {
                    st.push_back(i);
                } else {
                    maxLen = max(maxLen, i - st.back());
                }
            }
        }
        return maxLen;
    }
