class Solution {
    public int longestValidParentheses(String s) {
        java.util.ArrayDeque<Integer> st = new java.util.ArrayDeque<>();
        st.push(-1);
        int maxLen = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                st.push(i);
            } else {
                st.pop();
                if (st.isEmpty()) {
                    st.push(i);
                } else {
                    maxLen = Math.max(maxLen, i - st.peek());
                }
            }
        }
        return maxLen;
    }
}

var longestValidParentheses = function(s) {
    const st = [-1];
    let maxLen = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '(') {
            st.push(i);
        } else {
            st.pop();
            if (st.length === 0) {
                st.push(i);
            } else {
                maxLen = Math.max(maxLen, i - st[st.length - 1]);
            }
        }
    }
    return maxLen;
};
